  hb:touch(cx - 0.40 * rx, cy - 0.44 * ry, {pressure=0.85})
  hb:wipe(0.45)
  hb:touch(cx - 0.50 * rx, cy - 0.14 * ry, {pressure=0.4})
end
function stem(cx, cy, rx, ry, sd)
